/* Generated by Trae Work */
/* 学习状态监视页：只读。默认不展示任何档案，点击「查询」后才拉取并渲染当前打卡进度；
   同一设备一天内第 2 次点击查询会弹出抽奖弹窗（仅可点「立即抽奖」关闭），
   奖金 0.88~18.88 元纯随机，抽奖结果实时反传到学习端（A 端）。 */
"use strict";
(function () {
  const CLOUD = "https://ntfy.sh";
  let es = null;
  /* profiles: Map(name -> 快照对象)，仅保留每人最新一条 */
  const profiles = new Map();

  function esc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c])); }

  function topicFromUrl() {
    return new URLSearchParams(location.search).get("topic") || (window.CHECKIN_TOPIC || "");
  }

  function render() {
    const root = document.getElementById("status-root");
    const meta = document.getElementById("status-meta");
    if (!profiles.size) return;
    /* 按打卡时间倒序（updated_at 为 "YYYY-MM-DD HH:MM:SS"，字典序即时间序） */
    const list = [...profiles.values()].sort((a, b) => String(b.updated_at || "").localeCompare(String(a.updated_at || "")));
    meta.textContent = `频道：${topicFromUrl()} · 共 ${list.length} 位学习者 · 实时连接中（快照保留约 12 小时）`;
    root.innerHTML = list.map(p => {
      const s = p.summary || {};
      const lessons = (p.lessons || []).map(l => `
        <div class="plan-lesson ${l.track || ""} ${l.status}">
          <div class="pl-head">
            <span class="pl-time">${esc(l.time || "")}</span>
            <div class="pl-goal">
              <div class="pl-goal-text">${esc(l.label || "")}</div>
              ${l.done_at ? `<div class="pl-ts muted">打卡时间：${esc(l.done_at)}</div>` : ""}
            </div>
            <span class="badge ${l.status === "done" ? "ok" : l.status === "skipped" ? "miss" : "warnb"}">${l.status === "done" ? "已完成" : l.status === "skipped" ? "已跳过" : "进行中/待完成"}</span>
          </div>
          <div class="prog"><div class="prog-fill" style="width:${l.status === "done" ? 100 : 0}%"></div></div>
          ${(l.photos || []).length ? `<div class="pl-photos">${(l.photos || []).map(u => `<a href="${esc(u)}" target="_blank" rel="noopener" class="pl-photo-link"><img src="${esc(u)}" alt="打卡笔记照片"></a>`).join("")}<span class="muted pl-ts">点击查看笔记原图</span></div>` : ""}
        </div>`).join("");
      return `
      <div class="status-card">
        <div class="plan-summary">
          <div class="plan-date">${esc(p.name || "匿名学习者")} 的今日进度（${esc(p.date || "")}）<span class="muted pl-ts" style="margin-left:8px;">更新于 ${esc(p.updated_at || "")}</span></div>
          <div class="plan-pct">${s.percent || 0}%<small>（${s.done || 0}/${s.total || 0} 节${s.skipped ? ` · 跳过 ${s.skipped}` : ""}）</small></div>
        </div>
        <div class="prog big"><div class="prog-fill" style="width:${s.percent || 0}%"></div></div>
        ${lessons || `<div class="notice empty">快照里没有课程明细。</div>`}
      </div>`;
    }).join("");
  }

  /* ---------- 查询：一次性拉取历史快照 + 建立 SSE 实时订阅 ---------- */
  async function fetchOnce() {
    const root = document.getElementById("status-root");
    const topic = topicFromUrl();
    try {
      const res = await fetchTimeout(`${CLOUD}/${topic}/json?poll=1&since=12h`);
      if (!res.ok) throw new Error("HTTP " + res.status);
      const text = await res.text();
      text.trim().split(/\n/).forEach(line => {
        try {
          const m = JSON.parse(line);
          if (m.event !== "message" || !m.message) return;
          const snap = JSON.parse(m.message);
          if (snap && snap.app === "yyy-prep-checkin") profiles.set(snap.name || "匿名学习者", snap);
        } catch (e) { /* 跳过坏行 */ }
      });
      if (profiles.size) render();
      else root.innerHTML = `<div class="notice empty"><strong>当前暂无打卡档案。</strong>学习端完成一次打卡同步后，再点「查询」即可看到最新进度。</div>`;
    } catch (e) {
      root.innerHTML = `<div class="notice empty"><strong>查询失败（${esc(e.name === "AbortError" ? "请求超时" : e.message)}）。</strong>多为当前网络无法直连 ntfy.sh，可切换网络后重试。</div>`;
    }
  }

  function connect() {
    const meta = document.getElementById("status-meta");
    const topic = topicFromUrl();
    if (!topic) {
      document.getElementById("status-root").innerHTML = `<div class="notice empty"><strong>缺少频道配置。</strong>本站未设置 CHECKIN_TOPIC 常量，或链接缺少 ?topic=… 参数。</div>`;
      return;
    }
    if (es) es.close();
    try {
      es = new EventSource(`${CLOUD}/${topic}/sse?since=12h`);
      es.onopen = () => { meta.textContent = `频道：${topic} · 实时连接中`; };
      es.onmessage = ev => {
        try {
          const m = JSON.parse(ev.data);
          if (m.event !== "message" || !m.message) return;
          const snap = JSON.parse(m.message);
          if (snap && snap.app === "yyy-prep-checkin") {
            profiles.set(snap.name || "匿名学习者", snap);
            render();
          }
        } catch (e) { /* 非打卡消息忽略 */ }
      };
      es.onerror = () => {
        meta.textContent = "实时连接断开/失败，自动重连中…（多为当前网络无法直连 ntfy.sh，可切换网络后点「立即刷新」）";
      };
    } catch (e) { /* 查询阶段已展示错误提示 */ }
  }

  function fetchTimeout(url, opts = {}, ms = 12000) {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), ms);
    return fetch(url, { ...opts, signal: c.signal }).finally(() => clearTimeout(t));
  }

  /* ---------- 每日查询计数与抽奖 ---------- */
  function todayStr() { return fmtDate(new Date()); }

  function bumpQueryCount() {
    const d = todayStr();
    const rec = Store.get("status_query", {});
    const count = (rec && rec.date === d ? rec.count : 0) + 1;
    Store.set("status_query", { date: d, count });
    return count;
  }

  function deviceId() {
    let id = Store.get("lottery_device", "");
    if (!id) {
      const a = new Uint8Array(8);
      (crypto || {}).getRandomValues ? crypto.getRandomValues(a) : a.forEach((_, i) => a[i] = Math.floor(Math.random() * 256));
      id = "dev-" + [...a].map(x => x.toString(16).padStart(2, "0")).join("");
      Store.set("lottery_device", id);
    }
    return id;
  }

  async function publishLottery(amount, date, time) {
    const topic = topicFromUrl();
    if (!topic) return;
    try {
      await fetchTimeout(CLOUD + "/" + topic, {
        method: "POST",
        headers: { "X-Title": "Daily Lottery", "X-Tags": "tada" },
        body: JSON.stringify({ app: "yyy-lottery", device: deviceId(), amount, date, time })
      });
    } catch (e) { /* 结果反传失败不影响本机抽奖展示 */ }
  }

  /* 抽奖弹窗：遮罩/Esc 均不可关闭，唯一出口是「立即抽奖」按钮 */
  function showLotteryModal() {
    if (document.getElementById("lottery-mask")) return;
    const mask = document.createElement("div");
    mask.className = "lottery-mask";
    mask.id = "lottery-mask";
    mask.innerHTML = `
      <div class="lottery-card">
        <h3>🎁 恭喜触发抽奖</h3>
        <p class="lt-desc">本设备今日第 2 次查询，获得一次抽奖机会！<br>奖金 <strong>0.88 ~ 18.88 元</strong> 纯随机，结果将同步到学习端。</p>
        <button class="btn" id="lottery-go">🎲 立即抽奖</button>
      </div>`;
    document.body.appendChild(mask);
    const go = document.getElementById("lottery-go");
    go.addEventListener("click", async () => {
      go.disabled = true;
      go.textContent = "🎲 抽奖中…";
      go.classList.add("lt-spin");
      /* 概率纯随机：0.88 + [0,18) 均匀分布，保留两位小数 → 0.88~18.88 */
      const amount = (Math.round((0.88 + Math.random() * 18) * 100) / 100).toFixed(2);
      const d = todayStr();
      const time = new Date().toLocaleTimeString("zh-CN", { hour12: false });
      Store.set("lottery_done", { date: d, amount });
      await publishLottery(amount, d, time);
      const card = mask.querySelector(".lottery-card");
      card.innerHTML = `
        <h3>🎉 抽奖结果</h3>
        <div class="lt-amount">¥${esc(amount)}</div>
        <p class="lt-desc">奖金已同步到学习端（A 端），请留意打卡面板的抽奖动态。</p>`;
      setTimeout(() => { mask.remove(); }, 2000);
    });
  }

  function maybeLottery() {
    const done = Store.get("lottery_done", {});
    if (done && done.date === todayStr()) return; /* 当天已抽过，不再弹 */
    if (bumpQueryCount() >= 2) showLotteryModal();
  }

  async function doQuery() {
    const refresh = document.getElementById("status-refresh");
    if (refresh) refresh.style.display = "";
    document.getElementById("status-root").innerHTML = `<div class="notice info">正在查询当前打卡进度…</div>`;
    await fetchOnce();
    connect();
  }

  document.addEventListener("DOMContentLoaded", () => {
    if (!document.getElementById("status-root")) return;
    /* 默认只显示查询按钮：不连接、不渲染任何档案 */
    const root = document.getElementById("status-root");
    const refresh = document.getElementById("status-refresh");
    if (refresh) refresh.style.display = "none";
    root.innerHTML = `
      <div class="query-gate">
        <p class="muted" style="margin-bottom:18px;">点击查询后才会展现当前打卡进度（同一设备一天内第 2 次查询有抽奖机会）。</p>
        <button class="btn" id="status-query">🔍 查询当前打卡进度</button>
      </div>`;
    document.getElementById("status-query").addEventListener("click", async () => {
      bumpQueryCount(); /* 计数与抽奖判定放在查询后，避免弹窗打断查询 */
      await doQuery();
      maybeLottery();
    });
    if (refresh) refresh.addEventListener("click", doQuery);

    /* 照片灯箱预览：点击缩略图页内放大 */
    const lb = document.createElement("div");
    lb.className = "lightbox";
    lb.innerHTML = `<img alt="笔记照片预览"><button class="btn small lb-close">关闭 ✕</button>`;
    lb.style.display = "none";
    document.body.appendChild(lb);
    lb.addEventListener("click", e => {
      if (!e.target.closest("img")) { lb.style.display = "none"; lb.querySelector("img").src = ""; }
    });
    document.addEventListener("keydown", e => { if (e.key === "Escape") { lb.style.display = "none"; lb.querySelector("img").src = ""; } });
    document.getElementById("status-root").addEventListener("click", e => {
      const a = e.target.closest(".pl-photo-link");
      if (a) {
        e.preventDefault();
        lb.querySelector("img").src = a.getAttribute("href");
        lb.style.display = "flex";
      }
    });
  });
})();
